INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1480, 'maozi-cloud-system.yml', 'DEFAULT_GROUP', 'project:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\napplication-port: ${application-dev-port:4000}\napplication-dubbo-port: ${application-dev-dubbo-port:20881}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\napplication-datasource-db-name: maozi-cloud-system-localhost-db\n\napplication-project-whitelist: /user/platform/v1/getToken,/config/global/v1/system/get\n\napplication-project-system: \n  projectName: 小猫子\n  corporationName: 小猫子\n  icon: http://dummyimage.com/100x100\n  environment: ${project.environment}\n  description: 小猫子个人脚手架\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭', 'b29a5d54487e7f0e20fa096d40ea09f1', '2023-06-11 10:18:10', '2026-06-11 10:36:18', 'nacos', '172.18.0.1', '', '', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1483, 'maozi-cloud-monitor.yml', 'DEFAULT_GROUP', 'project:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\napplication-port: ${application-dev-port:2000}\n\nspring:\n  security:\n    user:\n      name: admin\n      password: admin\n      \n  boot:\n    admin:\n      discovery: \n        services: maozi-cloud-*\n      ui:\n        external-views:\n        \n          - label: \"注册中心\"\n            url: \"http://localhost:8848/nacos/#/configurationManagement?serverId=center&group=&dataId=&namespace=&pageSize=&pageNo=&appName=\"\n            iframe: true\n            order: 2002\n\n          - label: \"容器管理\"\n            url: \"http://localhost:9000\"\n            iframe: true\n            order: 2004\n\n          - label: \"Arthas管理\"\n            url: \"http://localhost:9080\"\n            iframe: true\n            order: 2005', '2287669d800fb855af89e4e74233d020', '2023-06-11 10:22:41', '2026-06-11 10:33:32', 'nacos', '172.18.0.1', '', '', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1497, 'maozi-cloud-oauth.yml', 'DEFAULT_GROUP', 'project:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\napplication-port: ${application-dev-port:3000}\napplication-dubbo-port: ${application-dev-dubbo-port:20880}\n\n# application-datasource-jdbc-url: localhost:3306/maozi-cloud-test-db\n# application-datasource-jdbc-username: root\n# application-datasource-jdbc-password: password\n\napplication-datasource-db-name: maozi-cloud-oauth-localhost-db\n\napplication-redis-database: 3\n\napplication-project-whitelist: ', 'c98c9e868bc197df9f27610ae48fea4a', '2024-01-02 10:40:48', '2026-06-11 16:31:57', 'nacos', '172.18.0.1', '', '', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1515, 'boot-lock.yml', 'DEFAULT_GROUP', 'spring:\n  lock:\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    password: ${spring.data.redis.password}\n    database: ${spring.data.redis.database:0}\n    #waitTime: 60 #获取锁最长阻塞时间（默认：60，单位：秒）\n    #leaseTime: 60 #已获取锁后自动释放时间（默认：60，单位：秒）\n    #redis集群配置 如 redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    #spring.klock.address 和 spring.klock.cluster-server.node-addresses 选其一即可\n    #cluster-server.node-addresses:', '1b41138ceeb9733a9ee3c6ab3e83fb0e', '2024-01-02 15:26:36', '2026-05-08 14:49:22', 'nacos', '172.18.0.1', '', '', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1519, 'boot-monitor.yml', 'DEFAULT_GROUP', 'spring:  \r\n  security:\r\n    user:\r\n      name: admin\r\n      password: admin\r\n  boot: \r\n    admin: \r\n      discovery: \r\n        services: maozi-cloud-*\r\n      client:\r\n        # url: http://localhost:8000\r\n        username: admin\r\n        password: admin\r\n        # auto-deregistration: true\r\n        # instance: \r\n        #   prefer-ip: true\r\n        #   metadata: \r\n        #     tags: \r\n        #       environment: 本地\r\n\r\nendpoints:\r\n  dubbo:\r\n    enabled: true\r\n\r\nmanagement:\r\n  info.env.enabled: true\r\n  health:\r\n    dubbo:\r\n      status:\r\n        defaults: memory\r\n        extras: load,threadpool\r\n  endpoints:\r\n    web:\r\n      exposure:\r\n        include: \'*\'\r\n  endpoint:\r\n    dubbo:\r\n      enabled: true\r\n    dubbo-shutdown:\r\n      enabled: true\r\n    dubbo-configs:\r\n      enabled: true\r\n    dubbo-services:\r\n      enabled: true\r\n    dubbo-references:\r\n      enabled: true\r\n    dubbo-properties:\r\n      enabled: true\r\n    health:\r\n      show-details: ALWAYS\r\n      probes.enabled: true', '6d9bdb9efc506c1238d1f1541f54c004', '2024-01-02 15:28:35', '2024-01-02 15:28:35', NULL, '172.30.0.1', '', '', NULL, NULL, NULL, 'yaml', NULL);
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1520, 'cloud-oauth.yml', 'DEFAULT_GROUP', 'spring:\n  security:\n    oauth2:\n      resourceserver:\n        opaquetoken:\n          # http 或 rpc\n          mode: rpc\n          # 匿名token自省端点\n          introspection-uri: http://127.0.0.1:3000/oauth2/introspect\n          # 客户端id\n          client-id: system\n          # 客户端秘钥\n          client-secret: 123456\n\n# security:\n#   oauth2:\n#     client: \n#       client-id: system\n#       client-secret: 123456\n#       access-token-uri: http://maozi-cloud-oauth:1000/oauth/token\n#       user-authorization-uri: http://maozi-cloud-oauth:1000/oauth/authorize\n#     resource:\n#       type: dubbo\n#       user-info-uri: http', '65373da480d0f659086512055267d9f0', '2024-01-02 15:41:35', '2026-06-11 13:46:15', 'nacos', '172.18.0.1', '', '', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (1564, 'boot-db.yml', 'DEFAULT_GROUP', 'mybatis-plus:\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  configuration: \n    map-underscore-to-camel-case: true\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  global-config: \n    refresh: false\n    banner: false\n    db-config:\n      db-type: mysql\n      id-type: AUTO\n      field-strategy: NOT_NULL\n      column-like: false\n      capital-mode: true\n      logic-delete-value: 1\n      logic-not-delete-value: 0\n\nmybatis-plus-join:\n  banner: false\n  table-alias: main\n\nmybatis:\n  configuration:\n    cache-enabled: false\n\nspring: \n  flyway: \n    enabled: true\n    table: system_table_flyway\n    clean-disabled: true\n    out-of-order: true\n    baseline-on-migrate: true\n    baseline-version: 0\n    locations: classpath:db\n    encoding: UTF-8', '6b82a3996631502d935dd3831737dd42', '2024-01-07 08:14:15', '2026-06-05 16:42:05', 'nacos', '172.18.0.1', '', '', '', '', '', 'yaml', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`) VALUES (3287, 'a.yml', 'DEFAULT_GROUP', 'a=abc', '1c8128107bd726f312947b043e28572a', '2026-02-28 07:44:31', '2026-02-28 07:45:11', 'nacos', '172.18.0.1', '', '75bc1675-1e8e-4099-b2f2-d9482ce14f4e', '', '', '', 'properties', '');
